import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { Gauge, Limit, Peer, ResetKind } from '../types'

const PANE = 'sessions-pane'
const gauge = atom({ plugin: 'session-hub', key: 'gauge' } as const, null)
const tick = atom({ plugin: 'session-hub', key: 'tick' } as const, 0)
const confirming = atom({ plugin: 'session-hub', key: 'confirming' } as const, null)

// 現在のレート制限を取り直す (バンドで使う)
const snapshot = async ($: any): Promise<Gauge> => ({ limits: (await $.session.usage()).rateLimits })

const PEER_STYLE: Record<string, { color: string; icon: string }> = {
  processing: { color: 'cyan', icon: '🔥' },
  waiting_input: { color: 'yellow', icon: '✋' },
  done: { color: 'green', icon: '🎉' },
  error: { color: 'red', icon: '🚨' },
}

const ageLabel = (sec: number) =>
  sec < 60 ? `${sec}s` : sec < 3600 ? `${Math.floor(sec / 60)}m` : `${Math.floor(sec / 3600)}h`

// cwd からプロジェクト名を出す。worktree (<repo>/.claude/worktrees/<name>) は親リポジトリにまとめる
const projectOf = (cwd?: string): string => {
  if (!cwd) return '?'
  const root = cwd.split('/.claude/worktrees/')[0]

  return root.split('/').filter(Boolean).pop() ?? '?'
}

type AgentInfo = { name: string; kind?: string }

// `claude agents --json` の生きているセッション。name は普段見ているタイトルで、agent-status の
// name (hook が決める。最初の指示文などになりがち) より優先する。取れなければ空で、
// agent-status の name を使う。
const agentInfos = async ($: any): Promise<Map<string, AgentInfo>> => {
  const infos = new Map<string, AgentInfo>()
  try {
    const { exitCode, stdout } = await $.process.run(['claude', 'agents', '--json'], { timeoutMs: 5000 })
    if (exitCode === 0) {
      for (const a of JSON.parse(stdout)) {
        if (a.sessionId) infos.set(a.sessionId, { name: a.name, kind: a.kind })
      }
    }
  } catch {
    // claude が見つからない・出力が壊れているときは agent-status の name に任せる
  }

  return infos
}

// claude/agent-status.sh が書く他セッションの状態を読む。
// statusline-command.sh と同じく、15 分止まったものと 60 秒を過ぎた done は除く (削除は向こうに任せる)。
// 表示するセッションの上限。超えたら更新が新しい順に残す
const MAX_PEERS = 5

const loadPeers = async ($: any): Promise<Peer[]> => {
  const self = await $.session.id()
  const dir = `${await $.env.get('HOME')}/.claude/agent-status`
  const now = Math.floor((await $.clock.now()) / 1000)
  const entries = await $.fs.list(dir).catch(() => [])
  const infos = await agentInfos($)
  const peers: Peer[] = []

  for (const { name } of entries) {
    if (!name.endsWith('.json')) continue
    try {
      const j = JSON.parse(await $.fs.read(`${dir}/${name}`))
      const ageSec = Math.max(0, now - (j.updated_at ?? 0))
      // done は 60 秒で外す。更新が止まっているだけのものは、生きていれば出す。
      // agents が取れないときだけ、生死が分からないので 15 分止まったものを外す
      const isStale = (j.state === 'done' && ageSec > 60) || (infos.size === 0 && ageSec > 900)
      // agents に載っていない (終了して resume もできない) セッションは、一覧が取れているときだけ除く
      const isLive = infos.size === 0 || infos.has(j.session_id)
      if (j.session_id && j.session_id !== self && !isStale && isLive && PEER_STYLE[j.state]) {
        peers.push({ id: j.session_id, name: infos.get(j.session_id)?.name || j.name || '?',
          kind: infos.get(j.session_id)?.kind, state: j.state, project: projectOf(j.cwd), ageSec })
      }
    } catch {
      // 書き込み途中などで壊れたファイルは次回の読み込みに任せる
    }
  }

  return peers.sort((a, b) => a.ageSec - b.ageSec).slice(0, MAX_PEERS)
}

type Group = { label: string; peers: Peer[] }

// プロジェクトごとにまとめる (名前順)
const groupPeers = (peers: Peer[]): Group[] =>
  [...new Set(peers.map(p => p.project))]
    .sort((a, b) => a.localeCompare(b))
    .map(label => ({ label, peers: peers.filter(p => p.project === label) }))

type Pick = (peer: Peer) => void

// 名前を押すと、そのセッションへ切り替える。バックグラウンドで動いているものは
// /resume できない (Claude Code が断る) ので、押せない表示だけにする。
const PeerItem = ({ Box, Button, Text, peer, pick }: { Box: any; Button: any; Text: any; peer: Peer; pick: Pick }) => (
  <Box>
    <Text color={PEER_STYLE[peer.state].color}>{PEER_STYLE[peer.state].icon} </Text>
    {peer.kind === 'background' ? (
      <Text>{peer.name}</Text>
    ) : (
      <Button key={`peer-${peer.id}`} label={peer.name} onPress={() => pick(peer)} />
    )}
    <Text dimColor> {ageLabel(peer.ageSec)}</Text>
  </Box>
)

const PeerGroup = ({ Box, Button, Text, g, pick }: { Box: any; Button: any; Text: any; g: Group; pick: Pick }) => (
  <Box flexDirection="column">
    <Text bold>{g.label}</Text>
    <Box flexDirection="column" paddingLeft={2}>
      {g.peers.map(peer => (
        <PeerItem key={peer.id} Box={Box} Button={Button} Text={Text} peer={peer} pick={pick} />
      ))}
    </Box>
  </Box>
)

// 中央で左右に分け、プロジェクトを 2 つずつ見出しの下に縦並びで出す
const PeerGroups = ({ Box, Button, Text, groups, pick }: { Box: any; Button: any; Text: any; groups: Group[]; pick: Pick }) => {
  const lines: Group[][] = []
  for (let i = 0; i < groups.length; i += 2) lines.push(groups.slice(i, i + 2))

  return (
    <Box flexDirection="column">
      {lines.map(line => (
        <Box key={line[0].label} flexDirection="row">
          {line.map(g => (
            <Box key={g.label} width="50%">
              <PeerGroup Box={Box} Button={Button} Text={Text} g={g} pick={pick} />
            </Box>
          ))}
        </Box>
      ))}
    </Box>
  )
}

// /resume <id> を打ったのと同じ動作で、このプロセスごと選んだセッションへ切り替える
const switchTo = async ($: any, peer: Peer) => {
  try {
    await $.command.run({ command: 'resume', args: peer.id })
  } catch (err) {
    await $.ui.toast(`${peer.name} に切り替えられませんでした: ${String(err)}`)
  }
}

// 制限に達したとみなす使用率
const LIMIT_PERCENT = 100

// 1 週間制限が先。そちらが尽きていれば 5 時間制限のリセットは意味が薄い
const reachedLimit = (limits: Limit[]): ResetKind | null => {
  const isHit = (kind: string) => limits.some(l => l.kind === kind && l.percentUsed >= LIMIT_PERCENT)

  return isHit('seven_day') ? 'seven_day' : isHit('five_hour') ? 'five_hour' : null
}

// どちらも実体は /limit-reset。A (リセット権) か B (週の枠を使った 5h リセット) のどちらが動くかは
// Claude Code 側が決める。ここで変えられるのは案内と確認の文言だけ。
const RESET_TEXT: Record<ResetKind, { notice: string; button: string; ask: string }> = {
  five_hour: {
    notice: '5 時間制限に達しました · 週間の枠を少し使って 5h をリセットできます (週 1 回)',
    button: 'リセットする',
    ask: '週間の枠を少し使って 5 時間制限をリセットします。よろしいですか?',
  },
  seven_day: {
    notice: '1 週間制限に達しました · リセット権があれば使えます',
    button: 'リセット権を使う',
    ask: 'リセット権を使って制限を回復します。よろしいですか?',
  },
}

const openPane = async ($: any) => {
  await $.ui.open({ id: PANE, title: 'Sessions' })
  await update($, tick, n => n + 1)
}

const runReset = async ($: any) => {
  await update($, confirming, () => null)
  try {
    await $.command.run({ command: 'limit-reset' })
  } catch (err) {
    await $.ui.toast(`リセットできませんでした: ${String(err)}`)
  }
}

export const register: Register = on => {
  let refresh: { cancel: () => void } | undefined

  on('session.start', async ($, e, next) => {
    // 他セッションの状態はファイルで変わるので、5 秒ごとに再描画する
    refresh?.cancel()
    refresh = $.clock.every(5000, () => void update($, tick, n => n + 1))

    await $.command.register({
      name: 'sessions',
      description: '他セッションの状態ペインを開く',
    })

    // 起動時から開いておく
    await $.ui.open({ id: PANE, title: 'Sessions' })

    return next(e)
  })

  // レート制限が動くたびに gauge を更新し、読んでいる描画を再描画する
  on('session.measure', async ($, e, next) => {
    await update($, gauge, () => ({ limits: e.rateLimits }))

    return next(e)
  })

  // ユーザーが入力したコマンドで開くので、狭い端末幅でも表示される
  on('command.run', { command: 'sessions' }, async $ => {
    await $.ui.open({ id: PANE, title: 'Sessions' })

    return { text: 'ペインを開きました。' }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    await read($, tick)
    const { Box, Button, Text } = $.ui.resolve(e)
    const peers = await loadPeers($)
    const room = Math.max(1, (e.viewport?.rows ?? 24) - 6)

    return (
      <Box flexDirection="column">
        {peers.length === 0 && <Text dimColor>他のセッションはありません。</Text>}
        <PeerGroups
          Box={Box}
          Button={Button}
          Text={Text}
          groups={groupPeers(peers.slice(0, room))}
          pick={peer => void switchTo($, peer)}
        />
      </Box>
    )
  })

  // ペインが閉じたらバンドを描き直し、ボタンを戻す
  on('ui.close', async ($, e, next) => {
    const result = await next(e)
    await update($, tick, n => n + 1)

    return result
  })

  // ペインが出ていないときだけ、開くボタンを出す。制限に達したときは、続けて確認つきのリセット案内を出す。
  // 押して開いたペインは、狭い端末でも表示される (起動時の自動オープンは 144 桁未満だと待機になる)
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    await read($, gauge) // session.measure での更新を購読するだけ。値は下で取り直す
    await read($, tick)
    const asked = await read($, confirming)

    if (e.props.hasSurvey) {
      return next(e)
    }

    const reached = reachedLimit((await snapshot($)).limits)
    const { Box, Button, Text } = $.ui.resolve(e)
    const text = reached && RESET_TEXT[reached]
    const isOpen = (await $.ui.panes()).some((p: any) => p.id === PANE && p.isPlaced)

    if (isOpen && !text) {
      return next(e)
    }

    return (
      <Box>
        {!isOpen && (
          <Button key="open-sessions" label="Sessions" onPress={() => void openPane($)} />
        )}
        {!isOpen && text && <Text> </Text>}
        {text && asked === reached ? (
          <Box>
            <Text color="yellow">{text.ask} </Text>
            <Button key="reset-yes" label="はい" onPress={() => void runReset($)} />
            <Text> </Text>
            <Button key="reset-no" label="やめる" onPress={() => update($, confirming, () => null)} />
          </Box>
        ) : text ? (
          <Box>
            <Text color="red">{text.notice} </Text>
            <Button key="reset" label={text.button} onPress={() => update($, confirming, () => reached)} />
          </Box>
        ) : null}
      </Box>
    )
  })
}

