export type Limit = { kind: string; percentUsed: number; resetsAt?: string }
export type Gauge = { limits: Limit[] }

export type ResetKind = 'five_hour' | 'seven_day'

export type Peer = { id: string; name: string; state: string; kind?: string; project: string; ageSec: number }

declare module 'claude-code' {
  interface PluginState {
    'session-hub': { gauge: Gauge | null; tick: number; confirming: ResetKind | null }
  }
}
